#include <bits/stdc++.h>
using namespace std;

int a[200005];

int main() {
    int n;
    cin >> n;
    for (int i = 1; i <= n; ++i) cin >> a[i];
    int solonnhat = -1000000000; // nhỏ hơn mọi giá trị được phép
    int vi_tri = 1;
    for (int i = 1; i <= n; ++i) {
        if (a[i] > solonnhat) { // so sánh nghiêm ngặt → giữ vị trí đầu tiên
            solonnhat = a[i];
            vi_tri = i;
        }
    }
    cout << solonnhat << " " << vi_tri << endl;
    return 0;
}

