#include <bits/stdc++.h>
using namespace std;

long long d[200005]; // mảng hiệu: khởi đầu là hiệu của mảng ban đầu
long long b[200005]; // mảng kết quả

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n, q;
    cin >> n >> q;
    long long truoc = 0;
    for (int i = 1; i <= n; ++i) {
        long long a;
        cin >> a;
        d[i] = a - truoc; // d[i] = a[i] - a[i-1]
        truoc = a;
    }
    while (q--) {
        int l, r;
        long long x;
        cin >> l >> r >> x;
        d[l] += x;     // Bật hiệu ứng từ l
        d[r+1] -= x;   // Chặn hiệu ứng sau r
    }
    for (int i = 1; i <= n; ++i) {
        b[i] = b[i-1] + d[i]; // Cộng dồn một vòng dựng lại mảng cuối
        cout << b[i];
        if (i < n) cout << ' ';
    }
    cout << "\n";
    return 0;
}

