#include <bits/stdc++.h>
using namespace std;

long long d[200005]; // mảng hiệu: khởi đầu là hiệu của mảng ban đầu
long long b[200005]; // mảng sau khi áp mọi lệnh
long long p[200005]; // prefix của mảng b

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n, q;
    cin >> n >> q;
    long long truoc = 0;
    for (int i = 1; i <= n; ++i) {
        long long a;
        cin >> a;
        d[i] = a - truoc; // d[i] = a[i] - a[i-1]
        truoc = a;
    }
    // Loại 1 đứng trước loại 2: đọc mọi sự kiện, ghi lệnh vào d,
    // lưu lại các câu hỏi để trả lời sau khi dựng prefix
    vector<int> cl, cr;
    while (q--) {
        int t;
        cin >> t;
        if (t == 1) {
            int l, r;
            long long x;
            cin >> l >> r >> x;
            d[l] += x;   // Bật hiệu ứng từ l
            d[r+1] -= x; // Chặn hiệu ứng sau r
        } else {
            int l, r;
            cin >> l >> r;
            cl.push_back(l);
            cr.push_back(r);
        }
    }
    for (int i = 1; i <= n; ++i) b[i] = b[i-1] + d[i]; // Mảng sau mọi lệnh
    for (int i = 1; i <= n; ++i) p[i] = p[i-1] + b[i]; // Prefix đúng lúc này
    for (int j = 0; j < (int)cl.size(); ++j) {
        cout << p[cr[j]] - p[cl[j]-1] << "\n"; // Mỗi câu hỏi một phép trừ
    }
    return 0;
}

