#include <bits/stdc++.h>
using namespace std;

int n;
long long k;
vector<long long> a;

// Tong so mieng cat duoc neu moi mieng dai it nhat L
long long soMieng(long long L) {
    long long tong = 0;
    for (int i = 0; i < n; ++i) {
        tong += a[i] / L;
        if (tong >= k) return tong;  // du roi, khong cong tiep
    }
    return tong;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    cin >> n >> k;
    a.resize(n);
    for (int i = 0; i < n; ++i) cin >> a[i];

    long long l = 1, r = 1000000000;  // doan dap an dang xet
    long long ket_qua = 0;            // chua co L nao thoa
    while (l <= r) {
        long long mid = l + (r - l) / 2;
        if (soMieng(mid) >= k) {
            ket_qua = mid;   // mid thoa, thu L lon hon
            l = mid + 1;
        } else {
            r = mid - 1;     // mid khong du mieng, thu L nho hon
        }
    }
    cout << ket_qua << "\n";
    return 0;
}

