#include <bits/stdc++.h>
using namespace std;

int n;
long long m;
vector<long long> w;

// Co the chia thanh nhieu nhat m doi, moi doi khong qua x khong?
bool check(long long x) {
    long long doi = 1, hien_tai = 0;
    for (int i = 0; i < n; ++i) {
        if (w[i] > x) return false;      // 1 phan vuot suc chua -> vo nghiem
        if (hien_tai + w[i] <= x) {
            hien_tai += w[i];            // doi hien tai nhan them phan i
        } else {
            doi++;                       // phai mo doi moi
            hien_tai = w[i];
            if (doi > m) return false;   // vuot so doi cho phep
        }
    }
    return true;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    cin >> n >> m;
    w.resize(n);
    for (int i = 0; i < n; ++i) cin >> w[i];

    long long l = 1, r = 0;
    for (int i = 0; i < n; ++i) r += w[i];  // bien tren: 1 doi lay het
    long long ket_qua = 0;
    while (l <= r) {
        long long mid = l + (r - l) / 2;
        if (check(mid)) {
            ket_qua = mid;   // mid dung, thu x nho hon
            r = mid - 1;
        } else {
            l = mid + 1;     // mid qua nho, can x lon hon
        }
    }
    cout << ket_qua << "\n";
    return 0;
}

