#include <bits/stdc++.h>
using namespace std;

const long long MOD = 1000000007;

int main() {
    int n;
    cin >> n;
    // Đệ quy có nhớ bản lặp (bottom-up): cùng ý tưởng "tính một lần ghi sổ"
    // nhưng đi từ F(1), F(2) lên F(n) — không tràn stack khi n tới 10^6
    if (n <= 2) {
        cout << 1 << "\n";
        return 0;
    }
    long long truoc = 1, hientai = 1, keTiep = 0;
    for (int i = 3; i <= n; i++) {
        keTiep = (truoc + hientai) % MOD;
        truoc = hientai;
        hientai = keTiep;
    }
    cout << hientai << "\n";
    return 0;
}

