#include <bits/stdc++.h>
using namespace std;

int main() {
    long long n;
    cin >> n;
    if (n == 1) {            // n = 1 chỉ có ước 1 = chính nó
        cout << -1 << "\n";
        return 0;
    }
    long long ketQua = 1;    // khi n nguyên tố, ước lớn nhất khác n là 1
    for (long long i = 2; i * i <= n; ++i) {
        if (n % i == 0) {    // i là ước nhỏ nhất >= 2 → n / i là ước lớn nhất khác n
            ketQua = n / i;
            break;           // thấy ước nhỏ nhất là dừng ngay
        }
    }
    cout << ketQua << "\n";
    return 0;
}

