solution.code:
#include <bits/stdc++.h>
using namespace std;

bool laNgTo[1000006];      // sàng nguyên tố tới 10^6 = căn của 10^12
bool biGach[1000006];      // biGach[k]: số (l + k) đã bị gạch

int main() {
    long long l, r;
    cin >> l >> r;

    // Bước 1: sàng Eratosthenes tới 10^6
    for (int i = 2; i <= 1000000; ++i) laNgTo[i] = true;
    for (long long i = 2; i * i <= 1000000; ++i)
        if (laNgTo[i])
            for (long long j = i * i; j <= 1000000; j += i)
                laNgTo[j] = false;

    // Bước 2: với mỗi nguyên tố p, gạch các bội của p nằm trong [l, r]
    long long doDai = r - l + 1;
    for (long long p = 2; p <= 1000000; ++p) {
        if (!laNgTo[p]) continue;
        long long bd = (l + p - 1) / p * p;  // bội của p đầu tiên >= l
        if (bd == p) bd += p;                // không gạch chính p
        if (bd < p * p) bd = p * p;          // bội nhỏ hơn p*p đã có ước nhỏ hơn
        for (long long j = bd; j <= r; j += p)
            biGach[j - l] = true;
    }

    // Bước 3: số chưa bị gạch trong đoạn là nguyên tố
    long long dem = 0;
    for (long long x = max(l, 2LL); x <= r; ++x)
        if (!biGach[x - l]) dem++;
    cout << dem << "\n";
    return 0;
}

