#include <bits/stdc++.h>
using namespace std;

const int N = 10000000;
bool sang[N + 7];
int soNgTo[N + 7]; // soNgTo[i]: số lượng nguyên tố trong [1, i]

int main() {
    // Bước 1: sàng Eratosthenes
    for (int i = 2; i <= N; ++i) sang[i] = true;
    for (long long i = 2; i * i <= N; ++i)
        if (sang[i])
            for (long long j = i * i; j <= N; j += i)
                sang[j] = false;

    // Bước 2: prefix đếm (như Bài 4.1)
    soNgTo[0] = 0;
    soNgTo[1] = 0;
    for (int i = 2; i <= N; ++i)
        soNgTo[i] = soNgTo[i - 1] + (sang[i] ? 1 : 0);

    // Bước 3: mỗi truy vấn đọc một ô
    int q;
    scanf("%d", &q);
    while (q--) {
        int x;
        scanf("%d", &x);
        printf("%d\n", soNgTo[x]);
    }
    return 0;
}

