#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, W; cin >> n >> W;
    int w[105], v[105];
    for (int i = 1; i <= n; i++) cin >> w[i] >> v[i];
    long long dp[105][10005] = {0};
    for (int i = 1; i <= n; i++) {
        for (int j = 0; j <= W; j++) {
            dp[i][j] = dp[i-1][j];
            if (j >= w[i])
                dp[i][j] = max(dp[i][j], dp[i-1][j - w[i]] + v[i]);
        }
    }
    cout << dp[n][W];
    return 0;
}
